# Helper functions and actions for interacting with the Mosaiq Orders window.
def _find_orders_window() -> bool:
    return True if CommonActions.find_object(MosaiqOrdersObjects.dashboard_Orders_window) is not None else False

# Helper function to determine if a given value represents an order name.
def _is_order_name_value(value: str) -> bool:
    cleaned = (value or "").strip()
    if not cleaned:
        return False

    # Skip dates, times, and obvious non-order metadata fields.
    if re.fullmatch(r"\d{1,2}/\d{1,2}/\d{2,4}", cleaned):
        return False
    if re.fullmatch(r"\d{1,2}:\d{2}\s*(AM|PM)?", cleaned, re.IGNORECASE):
        return False

    ignored = {
        "type",
        "order status",
        "booking progress",
        "start date",
        "time",
        "electronic status",
        "order",
        "obs",
        "observation",
        "specimen source",
        "approved",
        "pending",
        "cancel",
        "close",
        "ok",
    }
    if cleaned.casefold() in ignored:
        return False

    # Real order names are usually descriptive text and not pure date/status text.
    if cleaned.isdigit():
        return False

    return True

# Helper functions for interacting with Squish objects and extracting their values.
def _get_object_value(obj) -> str:
    for attribute_name in ("value", "text", "name"):
        try:
            value = getattr(obj, attribute_name, None)
            if value is not None and str(value).strip():
                return str(value).strip()
        except Exception:
            continue
    return ""

#  To get object attribute
def _get_object_attribute(obj, attribute_name: str) -> str:
    try:
        value = getattr(obj, attribute_name, "")
        return str(value).strip() if value is not None else ""
    except Exception:
        return ""

# Click the Cancel button on the Observation Orders popup.
@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_cancel_button_observation_orders() -> bool:
    CommonActions.left_click_object(MosaiqOrdersObjects.ObsOrders_Cancel_Button)
    time.sleep(0.3)
    error_dialogs = CommonActions.get_all_objects_by_map({"text": objectmaphelper.Wildcard("Error*"), "type": "Window"})
    if error_dialogs:
        raise RuntimeError("An error dialog was shown after clicking Cancel on the Observation Orders popup")

    if not _find_orders_window():
        raise RuntimeError("The Orders window was not displayed after clicking Cancel on the Observation Orders popup")

    return True

# Click the All button in the Orders window.
@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_all_button() -> bool:
    if _find_orders_window():
        CommonActions.left_click_object(MosaiqOrdersObjects.All_Button)
        time.sleep(0.3)
        return True
    return False

# Click the Change button in the Orders window.
@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_change_button() -> bool:
    if _find_orders_window():
        CommonActions.left_click_object(MosaiqOrdersObjects.Change_Button)
        time.sleep(1)
        return True
    return False

# Parse order rows from OCR text.
def _parse_order_rows_from_ocr_text(raw_text: str) -> list[str]:
    date_and_trailer = re.compile(r"\d{1,2}/\d{1,2}/\d{2,4}\s*\*?\s*(.+)$")
    order_names: list[str] = []
    for line in raw_text.splitlines():
        match = date_and_trailer.search(line.strip())
        if not match:
            continue
        candidate = _clean_ocr_value(match.group(1).strip())
        if candidate and _is_order_name_value(candidate) and candidate not in order_names:
            order_names.append(candidate)
    return order_names

# Read all visible orders in the Orders window via OCR.
@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def read_all_orders_via_ocr() -> list[str]:
    order_names: list[str] = []
    try:
        first_order = read_first_order_name()
        if first_order:
            order_names.append(first_order)
    except Exception as ex:
        print(f"[Orders debug] could not read the highlighted first order: {ex!r}")

    raw_text = CommonActions.get_all_text_via_ocr_in_object(MosaiqOrdersObjects.dashboard_Orders_window) or ""
    for order_name in _parse_order_rows_from_ocr_text(raw_text):
        if order_name not in order_names:
            order_names.append(order_name)
    return order_names


_LB_GETCOUNT = 0x018B
_LB_GETTEXT = 0x0189
_LB_GETTEXTLEN = 0x018A

# Helper function to read ListBox rows via raw Win32 messages
def _read_listbox_rows_via_hwnd(hwnd: int) -> list[str]:
    """Best-effort read of a native control's rows via raw Win32 ListBox messages."""
    if not hwnd:
        return []

    user32 = ctypes.windll.user32
    try:
        row_count = user32.SendMessageW(hwnd, _LB_GETCOUNT, 0, 0)
    except Exception:
        return []

    if row_count <= 0:
        return []

    rows = []
    for index in range(row_count):
        try:
            text_len = user32.SendMessageW(hwnd, _LB_GETTEXTLEN, index, 0)
            if text_len <= 0:
                continue
            buffer = ctypes.create_unicode_buffer(text_len + 1)
            user32.SendMessageW(hwnd, _LB_GETTEXT, index, ctypes.byref(buffer))
            if buffer.value:
                rows.append(buffer.value)
        except Exception:
            continue
    return rows

# Read the Orders grid rows via raw Win32 messages against its native hwnd
@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def read_order_column_via_native_grid() -> list[str]:
    native_controls = CommonActions.get_all_objects_by_map(MosaiqOrdersObjects.Orders_Native_Grid_Controls)
    print(f"Found {len(native_controls)} native Orders grid control(s)")

    for control in native_controls:
        hwnd = getattr(control, "hwnd", None)
        print(f"  control hwnd={hwnd!r}")
        rows = _read_listbox_rows_via_hwnd(hwnd)
        print(f"    rows read via LB_GETTEXT: {rows}")
        if rows:
            return rows

    return []

# Read the Orders grid via native hwnd messages as a fallback
@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def read_order_column() -> list[str]:
    if not CommonActions.get_all_objects_by_map(MosaiqOrdersObjects.dashboard_Orders_window):
        raise RuntimeError("Failed to find the Orders window")

    order_cells = CommonActions.get_all_objects_by_map(MosaiqOrdersObjects.Order_Cell)
    print(f"Found {len(order_cells)} cells under Order_Cell")

    order_names = []
    for cell in order_cells:
        name = _get_object_attribute(cell, "name")
        value = _get_object_value(cell)
        print(f"  cell name={name!r} value={value!r}")

        # Only keep the "Order" column - "order row" excludes "order status row".
        if not (name.casefold().startswith("order row") or name.casefold() == "order"):
            continue
        if value:
            order_names.append(value)
    return order_names


# Extract the comments value from raw OCR text using a regular expression.
def _extract_comments_value_from_ocr_text(raw_text: str, label_regex: str) -> tuple[str, str]:
    pattern = re.compile(label_regex, re.IGNORECASE)
    for line in raw_text.splitlines():
        match = pattern.search(line)
        if match:
            value = match.group(1).strip()
            if value:
                value = re.sub(r"^[^A-Za-z0-9]+", "", value).strip()
                value = _clean_ocr_value(value)
                if value:
                    return value, line
    return "", ""

# Read the comments text from the Orders window using OCR.
@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def read_comments_text_orders_window(timeout_seconds: float = 5.0) -> str:
    raw_text = CommonActions.get_all_text_via_ocr_in_object(MosaiqOrdersObjects.dashboard_Orders_window) or ""
    value, matched_line = _extract_comments_value_from_ocr_text(raw_text, r"order\s+comments:\s*(.+)")
    print(f"[Comments debug] Order Comments matched line: {matched_line!r} -> value={value!r}")
    if not value:
        raise RuntimeError(f"Failed to find the Comments text on the Orders window. Raw OCR text: {raw_text!r}")
    return value

# Read the comments text from the Observation Orders popup using OCR.
@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def read_comments_text(timeout_seconds: float = 5.0) -> str:
    deadline = time.time() + timeout_seconds
    value = ""
    matched_line = ""
    raw_text = ""
    popup_title_present = False
    while time.time() < deadline:
        raw_text = CommonActions.get_all_text_via_ocr_in_object(MosaiqOrdersObjects.dashboard_Orders_window) or ""
        print(f"[Comments debug] Raw OCR text: {raw_text!r}")
        popup_title_present = "observation orders" in raw_text.casefold()
        value, matched_line = _extract_comments_value_from_ocr_text(raw_text, r"(?<!order )comments:\s*(.+)")
        if value and popup_title_present:
            break
        time.sleep(0.5)

    print(f"[Comments debug] popup title present: {popup_title_present}")
    print(f"[Comments debug] popup Comments matched line: {matched_line!r} -> value={value!r}")
    if not popup_title_present:
        raise RuntimeError(
            f"The Observation Orders popup does not appear to be open (its title text was not "
            f"found via OCR), so this Comments value cannot be trusted. Raw OCR text: {raw_text!r}"
        )
    if not value:
        raise RuntimeError(f"Failed to find the Comments text box. Raw OCR text: {raw_text!r}")
    return value


# Read the first order name from the main Orders grid.
@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def read_first_order_name() -> str:
    order_names = read_order_column()
    if not order_names:
        order_names = read_order_column_via_native_grid()
    if order_names:
        return order_names[0]
    return read_first_order_name_via_ocr()

# Extract the first order-like line from raw OCR text
def _first_order_like_line_from_ocr_text(raw_text: str) -> str:
    lines = [ln.strip() for ln in raw_text.splitlines() if ln.strip()]
    if not lines:
        return ""

    # Try to locate the header line containing the 'Order' column label, then
    # inspect the lines that follow for the first realistic Order value.
    header_idx = None
    for idx, ln in enumerate(lines):
        if "order" in ln.casefold():
            header_idx = idx
            break

    # denylist of short single-word column headers or UI labels (including button labels) to ignore
    _DENY_SINGLE_WORD_HEADERS = {
        "date",
        "start",
        "time",
        "order",
        "status",
        "type",
        "electronic",
        "booking",
        "progress",
        "alerts",
        "allergies",
        "danger",
        "comments",
        "reschedule",
        "from",
        "to",
        "next",
        "all",
        "view",
        # common button labels found at the right-side toolbar
        "change",
        "close",
        "add",
        "delete",
        "approve",
        "refresh",
        "ok",
        "cancel",
        "status",
        "history",
        "authorize",
        "verbal",
    }

    if header_idx is not None:
        # Search subsequent lines for an order-like rightmost column token
        for ln in lines[header_idx + 1 :]:
            # skip UI labels or lines that look like controls
            if ln.casefold().startswith("view") or ln.casefold().startswith("type"):
                continue
            # Split by column-like separators first
            col_tokens = re.split(r"\s{2,}|\t|\|", ln)
            if len(col_tokens) == 1:
                col_tokens = ln.split()
            # prefer the rightmost non-empty token
            for token in reversed(col_tokens):
                tok = token.strip()
                if not tok:
                    continue
                # normalize token for header denylist check
                tok_norm = re.sub(r"[^A-Za-z]", "", tok).casefold()
                if not tok_norm:
                    continue
                if tok_norm in _DENY_SINGLE_WORD_HEADERS:
                    continue
                if _is_order_name_value(tok):
                    alpha = re.sub(r"[^A-Za-z]", "", tok)
                    if len(alpha) >= 3:
                        return _clean_ocr_value(tok)

    # If header-based extraction failed, fall back to scanning every OCR line
    # and selecting the first line that looks like an order name (per previous heuristic).
    for ln in lines:
        if _is_order_name_value(ln):
            alpha = re.sub(r"[^A-Za-z]", "", ln)
            if len(alpha) >= 3:
                return _clean_ocr_value(ln)
    # final fallback: any small matching token found on any line
    for ln in lines:
        tokens = re.split(r"\s+|\|", ln)
        for tok in tokens:
            tok = tok.strip()
            if tok and _is_order_name_value(tok):
                return _clean_ocr_value(tok)
    return ""

# Clean OCR value by stripping stray trailing single-letter artifacts
def _clean_ocr_value(value: str) -> str:
    """Strip stray trailing single-letter OCR artifacts, e.g. 'MRI Brain a' -> 'MRI Brain'."""
    tokens = value.split()
    while len(tokens) > 1 and len(tokens[-1]) == 1 and tokens[-1].isalpha():
        tokens.pop()
    return " ".join(tokens) if tokens else value

# Read the Observation value from the bottom detail panel via OCR
def _observation_panel_value_from_ocr_text(raw_text: str) -> str:
    lines = [ln.strip() for ln in raw_text.splitlines() if ln.strip()]
    for idx, ln in enumerate(lines):
        if "danger code" in ln.casefold():
            for candidate in lines[idx + 1 :]:
                if _is_order_name_value(candidate):
                    return _clean_ocr_value(candidate)
            break
    return ""

# Read the first order name via OCR from the Orders panel
@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def read_first_order_name_via_ocr(ocr_timeout: int = 15000) -> str:
    raw_text = CommonActions.get_all_text_via_ocr_in_object(MosaiqOrdersObjects.dashboard_Orders_window) or ""
    #print(f"[OCR debug] raw OCR text: {raw_text!r}")

    order_name = _observation_panel_value_from_ocr_text(raw_text)
    if not order_name:
        order_name = _first_order_like_line_from_ocr_text(raw_text)
    if not order_name:
        raise RuntimeError(f"No order name could be read via OCR. Raw OCR text: {raw_text!r}")
    print(f"[OCR debug] selected OCR candidate: {order_name!r}")
    return order_name


# Compare the comments of the first order with the observation comments.
@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def compare_order_comments_with_observation_comments() -> bool:
    order_comments = read_comments_text_orders_window()
    print(f"Order Comments (before opening Observation Orders): {order_comments!r}")

    click_change_button()

    observation_comments = read_comments_text()
    print(f"Observation Orders Comments (after opening popup): {observation_comments!r}")

    if order_comments != observation_comments:
        raise AssertionError(
            f"Order Comments does not match the Observation Orders Comments: "
            f"order_comments={order_comments!r}, observation_comments={observation_comments!r}"
        )
    return True

